	b[15] = byte(g.schedWakeTick)
	b[16] = byte(g.scheduleSlot)
	b[17] = byte(g.schedListACount)
	for i := range g.schedListA {
		b[18+i] = byte(g.schedListA[i])
	}
	b[23] = byte(g.schedListBCount)
	for i := range g.schedListB {
		b[24+i] = byte(g.schedListB[i])
	}
	b[27] = byte(g.schedSeqIdx)
	b[28] = byte(g.schedFlags)
	b[29] = byte(g.schedPhase)
	b[30] = byte(g.schedNextHour)
